import sqlite3
from dataclasses import dataclass
import stripe
from langchain_core.tools import tool
PLAN_PRICES = {'basic': 299, 'plus': 599, 'pro': 1299}

@dataclass
class SubscriptionResult:
    device_id: str
    charge_id: str
    amount_cents: int
    new_group: str

def _cancel_previous_subscription(conn, device_id):
    row = conn.execute('SELECT stripe_sub_id FROM device_subscriptions WHERE device_id = ?', (device_id,)).fetchone()
    if row:
        stripe.Subscription.cancel(row[0])
        conn.execute('DELETE FROM device_subscriptions WHERE device_id = ?', (device_id,))

@tool
def purchase_and_move_device_subscription(device_id: str, plan_id: str, customer_id: str) -> SubscriptionResult:
    amount = PLAN_PRICES[plan_id]
    charge = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, confirm=True, metadata={'device_id': device_id, 'plan': plan_id})
    group = f'subscribed_{plan_id}'
    with sqlite3.connect('home.db') as conn:
        _cancel_previous_subscription(conn, device_id)
        conn.execute('UPDATE devices SET group_name = ? WHERE id = ?', (group, device_id))
    return SubscriptionResult(device_id, charge.id, amount, group)
